41	impl<'a> Macros<'a> {
42	  pub fn new(
43	    callback: MacroCallback,
44	    source_map: &'a SourceMap,
45	    diagnostics: &'a mut Vec<Diagnostic>,
46	  ) -> Self {
47	    Macros {
48	      macros: HashMap::new(),
49	      constants: HashMap::new(),
50	      callback,
51	      source_map,
52	      diagnostics,
53	      assignment_span: None,
54	      in_call: false,
55	    }
56	  }
