209	impl SourceLocation {
210	  pub fn from(source_map: &swc_core::common::SourceMap, span: swc_core::common::Span) -> Self {
211	    if span.lo.is_dummy() || span.hi.is_dummy() {
212	      return SourceLocation {
213	        start_line: 1,
214	        start_col: 1,
215	        end_line: 1,
216	        end_col: 2,
217	      };
218	    }
219	
220	    let start = source_map.lookup_char_pos(span.lo);
221	    let end = source_map.lookup_char_pos(span.hi);
222	    // SWC's columns are exclusive, ours are exclusive
223	    // SWC has 0-based columns, ours are 1-based (column + 1)
224	    SourceLocation {
225	      start_line: start.line,
226	      start_col: start.col_display + 1,
227	      end_line: end.line,
228	      end_col: end.col_display + 1,
229	    }
230	  }
231	}
