234	  fn partial_cmp(&self, other: &SourceLocation) -> Option<Ordering> {
235	    match self.start_line.cmp(&other.start_line) {
236	      Ordering::Equal => self.start_col.partial_cmp(&other.start_col),
237	      o => Some(o),
238	    }
239	  }
