  /// Convert a rejected macro callback value into a `MacroError`.
  ///
  /// The JS `callMacro` implementation rejects with an object of the shape
  /// `{type: 'LoadError' | 'EvaluationError', message: string}` so we can distinguish
  /// between errors that occur while loading the macro module and errors thrown while
  /// executing the macro. Anything else is treated as an evaluation error.
  fn napi_to_macro_error(value: JsUnknown, env: Env) -> napi::Result<MacroError> {
    if value.get_type()? == ValueType::Object {
      let obj = unsafe { value.cast::<JsObject>() };

      let message = match obj.get_named_property::<JsUnknown>("message") {
        Ok(m) if m.get_type()? == ValueType::String => {
          unsafe { m.cast::<JsString>() }.into_utf8()?.into_owned()?
        }
        _ => "Unknown error".into(),
      };

      let is_load_error = match obj.get_named_property::<JsUnknown>("type") {
        Ok(t) if t.get_type()? == ValueType::String => {
          unsafe { t.cast::<JsString>() }.into_utf8()?.into_owned()? == "LoadError"
        }
        _ => false,
      };

      if is_load_error {
        Ok(MacroError::LoadError(message))
      } else {
        Ok(MacroError::EvaluationError(message))
      }
    } else if value.get_type()? == ValueType::String {
      Ok(MacroError::EvaluationError(
        unsafe { value.cast::<JsString>() }.into_utf8()?.into_owned()?,
      ))
    } else {
      Ok(MacroError::EvaluationError("Unknown error".into()))
    }
